function Logo({ inverse = false }: { inverse?: boolean }) { const { t } = useLocale(); return <Link href="/" className={`brand-logo flex items-center gap-3 ${inverse ? "text-white" : "ni-t-ink"}`}><img src={mark} className="h-10 w-10 rounded-xl object-contain" alt={t("brand.name")} /><span className="font-display text-xl font-semibold tracking-tight whitespace-nowrap">{t("brand.name")}</span></Link>; }
function Button({ children, href, variant = "primary", onClick, type = "submit", disabled = false, "data-testid": testId }: { children: React.ReactNode; href?: string; variant?: "primary" | "quiet" | "outline"; onClick?: () => void; type?: "button" | "submit"; disabled?: boolean; "data-testid"?: string }) { const cls = `brand-button ni-btn ni-btn--${variant} disabled:cursor-not-allowed disabled:opacity-50`; if (href) return <Link href={href} className={cls} data-testid={testId}>{children}</Link>; return <button type={type} onClick={onClick} disabled={disabled} className={cls} data-testid={testId}>{children}</button>; }
function Pill({ children, tone = "sage" }: { children: React.ReactNode; tone?: "sage" | "gold" | "ink" }) { return <span className={`status-pill ni-verify ${tone === "gold" ? "ni-t-gold" : tone === "ink" ? "ni-t-ink" : "ni-t-sage-ink"}`}><span className="ni-mark" aria-hidden="true"><i/><i/><i/><i/></span>{children}</span>; }
