function Footer() { const { t } = useLocale(); return <footer className="site-footer ni-on-teal bg-[var(--ni-teal)]"><div className="mx-auto grid max-w-7xl gap-10 px-5 py-14 lg:grid-cols-[1.3fr_1fr_1fr_1fr] lg:px-8"><div><Logo inverse/><p className="mt-5 max-w-xs text-sm leading-7 ni-t-muted">Thoughtful Islamic learning, with a clearer path from curiosity to consistency.</p></div><div><p className="mb-4 text-xs font-bold uppercase tracking-[.18em] ni-t-gold-mid">{t("footer.explore")}</p><div className="flex flex-col gap-3 text-sm"><Link href="/courses">{t("nav.courses")}</Link><Link href="/teachers">{t("nav.tutors")}</Link><Link href="/requirements">{t("nav.requirements")}</Link><Link href="/contact-lms">{t("footer.contact")}</Link></div></div><div><p className="mb-4 text-xs font-bold uppercase tracking-[.18em] ni-t-gold-mid">{t("footer.learn")}</p><div className="flex flex-col gap-3 text-sm"><Link href="/how-it-works">{t("nav.howItWorks")}</Link><Link href="/about-lms">{t("brand.name")}</Link><Link href="/faqs">{t("nav.faqs")}</Link><Link href="/about-lms">{t("footer.privacy")}</Link></div></div><div><p className="mb-4 text-xs font-bold uppercase tracking-[.18em] ni-t-gold-mid">{t("home.noorWay")}</p><p className="text-sm leading-6 ni-t-muted">{t("footer.demo")}</p><Link href="/signup" className="mt-4 inline-flex text-sm font-bold text-white">{t("nav.join")} <ArrowRight size={15} className="ml-2"/></Link></div></div><div className="border-t border-white/10 px-5 py-5 text-center text-xs ni-t-muted">© 2026 Zufishan · LMS foundation · Demo content is clearly labelled</div></footer>; }
function SectionHeading({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy?: string; action?: React.ReactNode }) { return <div className="mb-9 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="ni-label mb-3 flex items-center gap-2"><span className="ni-mark" aria-hidden="true"><i/><i/><i/><i/></span>{eyebrow}</p><h2 className="font-display text-4xl leading-[1.04] tracking-tight ni-t-ink sm:text-5xl">{title}</h2>{copy && <p className="mt-4 max-w-xl text-base leading-7 ni-t-muted">{copy}</p>}</div>{action}</div>; }
function CourseCard({ course, index = 0 }: { course: typeof courses[number]; index?: number }) { return <Link href={`/courses/${course.slug}`} className="group overflow-hidden rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] shadow-[0_14px_40px_rgba(37,77,60,.06)] hover:-translate-y-1 hover:shadow-[0_18px_42px_rgba(37,77,60,.12)]"><div className="relative h-36 overflow-hidden" style={{ backgroundColor: index % 2 ? "var(--ni-sage-soft)" : "var(--ni-gold-soft)" }}><img src={courseVisuals[index % courseVisuals.length]} alt="" className="h-full w-full object-cover mix-blend-multiply opacity-75 transition duration-500 group-hover:scale-105"/><div className="absolute left-4 top-4"><Pill>{course.subject}</Pill></div><div className="absolute bottom-3 right-4 rounded-full bg-white/80 px-3 py-1 text-xs font-bold ni-t-ink">{course.duration}</div></div><div className="p-5"><div className="mb-3 flex items-center justify-between text-xs ni-t-muted"><span>{course.level}</span><span>{course.format}</span></div><h3 className="font-display text-2xl leading-tight ni-t-ink">{course.title}</h3><p className="mt-3 line-clamp-2 text-sm leading-6 ni-t-muted">{course.description}</p><div className="mt-5 flex items-center justify-between border-t border-[var(--ni-sage-soft)] pt-4 text-sm"><span className="font-semibold ni-t-moss-deep">{course.instructor.name}</span><ArrowRight size={17} className="ni-t-gold transition group-hover:translate-x-1"/></div></div></Link>; }
function TutorCard({ instructor, index = 0 }: { instructor: typeof instructors[number]; index?: number }) { return <Link href={`/teachers/${instructor.slug}`} className="group rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-5 shadow-[0_14px_40px_rgba(37,77,60,.05)] hover:-translate-y-1"><div className="flex items-start gap-4"><div className="relative h-16 w-16 shrink-0 overflow-hidden rounded-2xl bg-[var(--ni-sage-soft)]"><img src={tutorVisuals[index % tutorVisuals.length]} alt="" className="h-full w-full object-cover"/><span className="absolute bottom-1 right-1 h-3 w-3 rounded-full border-2 border-white bg-[var(--ni-gold-ink)]"/></div><div><h3 className="font-display text-xl ni-t-ink">{instructor.name}</h3><p className="mt-1 text-xs ni-t-muted">{instructor.experience} · {instructor.availability.timezone}</p></div></div><div className="mt-5 flex flex-wrap gap-2">{instructor.subjects.map((s) => <Pill key={s.name}>{s.name}</Pill>)}</div><p className="mt-4 text-sm leading-6 ni-t-muted">{instructor.bio}</p><div className="mt-5 flex items-center justify-between border-t border-[var(--ni-sage-soft)] pt-4 text-xs font-semibold ni-t-sage-ink"><span>{instructor.languages.join(" · ")}</span><span className="ni-t-gold">View profile <ArrowRight size={14} className="ml-1 inline"/></span></div></Link>; }
