function Filters({ onChange, placeholder, subject = "", onSubjectChange }: { onChange: (value: string) => void; placeholder?: string; subject?: string; onSubjectChange?: (value: string) => void }) { const { t } = useLocale(); return <div className="flex flex-col gap-3 rounded-2xl border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-3 shadow-sm md:flex-row"><div className="flex flex-1 items-center gap-3 rounded-xl bg-[var(--ni-sage-soft)] px-4"><Search size={18} className="ni-t-muted-soft"/><input aria-label={t("catalogue.search")} onChange={(e) => onChange(e.target.value)} placeholder={placeholder || t("catalogue.search")} className="w-full bg-transparent py-3 text-sm outline-none placeholder:text-[var(--ni-muted-soft)]"/></div><select aria-label={t("catalogue.allSubjects")} value={subject} onChange={(e) => onSubjectChange?.(e.target.value)} className="rounded-xl bg-[var(--ni-sage-soft)] px-4 py-3 text-sm ni-t-moss-deep outline-none"><option value="">{t("catalogue.allSubjects")}</option>{categories.map((c) => <option key={c} value={c}>{c}</option>)}</select><select className="rounded-xl bg-[var(--ni-sage-soft)] px-4 py-3 text-sm ni-t-moss-deep outline-none"><option>{t("catalogue.allLevels")}</option><option>Beginner</option><option>Intermediate</option></select><button className="inline-flex items-center justify-center gap-2 rounded-xl border border-[var(--ni-sage-line)] px-4 py-3 text-sm font-bold ni-t-sage-ink"><Filter size={16}/>{t("catalogue.moreFilters")}</button></div>; }
function PageIntro({ eyebrow, title, copy }: { eyebrow: string; title: string; copy: string }) { return <section className="bg-[var(--ni-bg)]"><div className="mx-auto max-w-7xl px-5 py-14 lg:px-8 lg:py-20"><p className="text-xs font-bold uppercase tracking-[.2em] ni-t-gold">{eyebrow}</p><h1 className="mt-4 max-w-3xl font-display text-6xl leading-[.98] tracking-tight ni-t-ink">{title}</h1><p className="mt-5 max-w-2xl text-lg leading-8 ni-t-muted">{copy}</p></div></section>; }
/**
 * `/courses?subject=...`, which is where the Our Courses panel points.
 *
 * The panel lists whatever subjects are actually published, so it cannot rely on the
 * fixed `/courses/category/...` routes, which name eight subjects by hand. Remounting on
 * the subject (`key`) is deliberate: CoursesPage seeds state from the prop once, so a new
 * subject has to arrive as a new instance to be picked up.
 */
function CoursesRoute() {
  const search = useSearch();
  const subject = new URLSearchParams(search).get("subject") ?? "";
  return <CoursesPage key={subject} initialSubject={subject}/>;
}
function CoursesPage({ initialSubject = "" }: { initialSubject?: string }) {
  const { t } = useLocale();
  const [query, setQuery] = useState("");
  const [subject, setSubject] = useState(initialSubject);
  const coursesQuery = trpc.schedulingPublic.publishedCourses.useQuery(undefined, { retry: false });
  type PublicCourseRow = { id: string; slug: string; title: string; description: string; subject: string; level: string; language: string; status: string; created_at: string };
  // The procedure returns a page object — { courses, total, limit, offset } — not a bare array.
  // Casting it straight to PublicCourseRow[] made `.filter` throw and blanked the whole page.
  const liveCourses: PublicCourseRow[] = coursesQuery.data?.ok ? (coursesQuery.data.data as { courses: PublicCourseRow[] }).courses ?? [] : [];
  const filtered = liveCourses.filter((course) => (!subject || course.subject.toLowerCase() === subject.toLowerCase()) && `${course.title} ${course.subject} ${course.description} ${course.language}`.toLowerCase().includes(query.toLowerCase()));
  return <><Header/><PageIntro eyebrow={t("catalogue.eyebrow")} title={t("catalogue.title")} copy={t("catalogue.copy")}/><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><Filters onChange={setQuery} subject={subject} onSubjectChange={setSubject}/>{coursesQuery.isLoading && <p className="mt-8 rounded-2xl bg-[var(--ni-sage-soft)] p-5 text-sm ni-t-muted">{t("catalogue.loadingPublished")}</p>}{coursesQuery.isError && <p className="mt-8 rounded-2xl bg-[var(--ni-clay-soft)] p-5 text-sm ni-t-clay" role="alert">{t("catalogue.courseDiscoveryUnavailable")}</p>}{!coursesQuery.isLoading && !coursesQuery.isError && <><div className="mb-7 mt-10 flex items-center justify-between"><p className="text-sm font-semibold ni-t-muted">{t("catalogue.publishedCourses")} · {filtered.length}</p><span className="text-xs ni-t-muted-soft">{t("catalogue.publicFieldsOnly")}</span></div>{filtered.length ? <div data-reveal-stagger className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">{filtered.map((course, index) => <Link key={course.id} href={`/courses/${course.slug}`} className="group overflow-hidden rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] shadow-[0_14px_40px_rgba(37,77,60,.06)] hover:-translate-y-1"><div className="relative h-36 overflow-hidden" style={{ backgroundColor: index % 2 ? "var(--ni-sage-soft)" : "var(--ni-gold-soft)" }}><img src={courseVisuals[index % courseVisuals.length]} alt="" className="h-full w-full object-cover mix-blend-multiply opacity-75"/><div className="absolute left-4 top-4"><Pill>{course.subject}</Pill></div></div><div className="p-5"><div className="mb-3 flex items-center justify-between text-xs ni-t-muted"><span>{course.level}</span><span>{course.language}</span></div><h3 className="font-display text-2xl leading-tight ni-t-ink">{course.title}</h3><p className="mt-3 line-clamp-3 text-sm leading-6 ni-t-muted">{course.description}</p><div className="mt-5 border-t border-[var(--ni-sage-soft)] pt-4 text-xs font-semibold ni-t-sage-ink">Published course · {course.status}</div></div></Link>)}</div> : <EmptyState title={t("catalogue.noneTitle")} copy={t("catalogue.noneCopy")}/>}</>}</main><Footer/></>;
}

function CourseDetail({ slug }: { slug: string }) {
  const { t } = useLocale();
  // The enrol button used to point at /login unconditionally, so a signed-in learner was
  // bounced to a login page instead of being enrolled. A visitor still has to sign in, but
  // returnTo carries them to enrolment afterwards rather than dropping them on a dashboard.
  const { isAuthenticated } = useAuth();
  const courseQuery = trpc.schedulingPublic.courseBySlug.useQuery({ slug }, { retry: false });
  type PublicCourseDetail = { id: string; slug: string; title: string; description: string; subject: string; level: string; language: string; status: string; created_at: string };
  const course: PublicCourseDetail | null = courseQuery.data?.ok ? courseQuery.data.data as PublicCourseDetail : null;
  if (courseQuery.isLoading) return <><Header/><main className="mx-auto max-w-5xl px-5 py-20"><p className="rounded-2xl bg-[var(--ni-sage-soft)] p-5 text-sm ni-t-muted">Loading the approved course…</p></main><Footer/></>;
  if (courseQuery.isError || !course) return <><Header/><main className="mx-auto max-w-5xl px-5 py-20"><p className="text-xs font-bold uppercase tracking-[.2em] ni-t-gold">Course details</p><h1 className="mt-4 font-display text-5xl">{t("catalogue.courseNotPublic")}</h1><p className="mt-4 max-w-2xl ni-t-muted">{t("catalogue.courseNotPublicCopy")}</p><Link href="/courses" className="mt-7 inline-flex rounded-full bg-[var(--ni-moss)] px-5 py-3 text-sm font-semibold text-white">{t("courseDetail.back")}</Link></main><Footer/></>;
  return <><Header/><main><div className="bg-[var(--ni-teal)] text-white"><div className="mx-auto max-w-7xl px-5 py-14 lg:px-8 lg:py-20"><Link href="/courses" className="text-sm text-[var(--ni-sage-line)]">← {t("courseDetail.back")}</Link><div className="mt-12 grid gap-12 lg:grid-cols-[1fr_.75fr]"><div><Pill tone="gold">{course.subject}</Pill><h1 className="mt-6 max-w-2xl font-display text-6xl leading-[.96]">{course.title}</h1><p className="mt-6 max-w-xl text-lg leading-8 text-[var(--ni-sage-line)]">{course.description}</p><div className="mt-8 flex flex-wrap gap-3"><Button href={isAuthenticated ? `/enrol/${course.id}` : `/login?returnTo=${encodeURIComponent(`/enrol/${course.id}`)}`}>{t("courseDetail.enrol")} <ArrowRight size={16}/></Button><TrialCTA context={{ courseSlug: course.slug }} label={t("courseDetail.requestTrial")}/></div></div><div className="overflow-hidden rounded-[2rem] bg-[var(--ni-sage-soft)] p-3"><img src={courseArt} alt="" className="h-72 w-full rounded-[1.5rem] object-cover"/></div></div></div></div><div className="mx-auto grid max-w-7xl gap-12 px-5 py-16 lg:grid-cols-[1.1fr_.7fr] lg:px-8"><div><p className="text-xs font-bold uppercase tracking-[.2em] ni-t-gold">{t("courseDetail.outline")}</p><h2 className="mt-3 font-display text-4xl ni-t-ink">{t("courseDetail.sequence")}</h2><div className="mt-8 rounded-2xl border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6 text-sm leading-7 ni-t-muted">Published course content is available through the connected course workspace. Lesson and module data will appear here when the protected course-content query is connected.</div></div><aside className="rounded-[1.5rem] bg-[var(--ni-sage-soft)] p-7"><p className="text-xs font-bold uppercase tracking-[.18em] ni-t-gold">{t("courseDetail.glance")}</p><div className="mt-6 space-y-5 text-sm"><Info label={t("courseDetail.level")} value={course.level}/><Info label={t("courseDetail.language")} value={course.language}/><Info label={t("courseDetail.instructor")} value="Instructor profile to be connected"/><Info label={t("courseDetail.format")} value="Course format to be connected"/></div><div className="mt-7 border-t border-[var(--ni-sage-line)] pt-5 text-sm leading-6 ni-t-muted"><ShieldCheck size={17} className="mb-2 ni-t-gold"/>{t("courseDetail.trust")}</div></aside></div></main><Footer/></>;
}

function TeachersPage({ initialSubject = "", initialGender = "", embedded = false }: { initialSubject?: string; initialGender?: string; embedded?: boolean }) {
  const { t } = useLocale();
  // The gender arrives as an opening filter the reader can clear, not as a locked query:
  // it seeds the same MarketplaceFilterState the sidebar edits.
  const [filters, setFilters] = useState<MarketplaceFilterState>({ ...emptyFilters, subjects: initialSubject ? [initialSubject] : [], gender: initialGender || undefined });
  const [page, setPage] = useState(0);
  const pageSize = 12;

  // Every filter is sent to the server; the browser never narrows the list itself.
  const instructorsQuery = trpc.schedulingPublic.instructors.useQuery({
    query: filters.query || undefined,
    subjects: filters.subjects.length ? filters.subjects : undefined,
    languages: filters.languages.length ? filters.languages : undefined,
    levels: filters.levels.length ? filters.levels : undefined,
    minRateMinor: filters.minRateMinor,
    maxRateMinor: filters.maxRateMinor,
    minYearsExperience: filters.minYearsExperience,
    gender: filters.gender === "male" || filters.gender === "female" ? filters.gender : undefined,
    country: filters.country || undefined,
    timezone: filters.timezone || undefined,
    sect: filters.sect as "Sunni" | "Shia" | "Other" | "Prefer not to say" | undefined,
    hasIjazah: filters.hasIjazah || undefined,
    minRating: filters.minRating as 1 | 2 | 3 | 4 | 4.5 | undefined,
    sort: filters.sort as "relevance" | "rate_asc" | "rate_desc" | "experience_desc",
    limit: pageSize,
    offset: page * pageSize,
  }, { retry: false });
  const facetsQuery = trpc.schedulingPublic.instructorFacets.useQuery(undefined, { retry: false });

  // The shape the server returns, including the presentation fields it attaches
  // for rows that are already published and approved.
  type PublicInstructorRow = DiscoveryInstructor & { public_profile_status: string };
  const result = instructorsQuery.data?.ok ? instructorsQuery.data.data as { instructors: PublicInstructorRow[]; total: number } : null;
  // `ok:false` is a handled server failure delivered over a successful request, so
  // isError does not catch it. Without this the page reports an empty marketplace
  // when discovery actually failed, which is indistinguishable to the reader.
  const discoveryFailed = instructorsQuery.isError || (instructorsQuery.data !== undefined && !instructorsQuery.data.ok);
  const instructors = result?.instructors ?? [];
  const total = result?.total ?? 0;
  // `ratingBuckets` and `rateRangeMinor` come from the same facet call, so the sidebar's counts
  // and slider bounds describe the same published roster the results are drawn from.
  type InstructorFacets = { subjects: string[]; languages: string[]; levels: string[]; rateRangeMinor?: { min: number; max: number } | null; ratingBuckets?: Array<{ minimum: number; count: number }> | null };
  const facets: InstructorFacets = facetsQuery.data?.ok ? facetsQuery.data.data as InstructorFacets : { subjects: [], languages: [], levels: [] };

  const updateFilters = (nextFilters: MarketplaceFilterState) => { setFilters(nextFilters); setPage(0); };

  return <>{!embedded && <Header/>}
    {/* The marketing intro belongs to the public /teachers page. Inside the learner dashboard
        the sidebar already names the module, so only the heading is carried across. */}
    {embedded ? <h1 className="sr-only">{t("teachers.title")}</h1> : <PageIntro eyebrow={t("teachers.eyebrow")} title={t("teachers.title")} copy={t("teachers.copy")}/>}
    <main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16">
      <div className="mb-6 flex flex-col gap-3 sm:flex-row sm:items-center">
        <label className="flex-1">
          <span className="sr-only">{t("teachers.search")}</span>
          <input
            type="search" value={filters.query} placeholder={t("discovery.searchTutors")}
            onChange={(event) => updateFilters({ ...filters, query: event.target.value })}
            className="w-full rounded-full border border-[var(--ni-sage-line)] bg-[var(--ni-field)] px-5 py-3 text-sm ni-t-ink outline-none focus-visible:ring-2 focus-visible:ring-[var(--ni-moss)]"
          />
        </label>
        <MarketplaceFilters variant="trigger" value={filters} onChange={updateFilters} facets={facets} resultCount={total} showRate showExperience sortOptions={[
            { value: "relevance", label: t("marketplace.sortRelevance") },
            { value: "rate_asc", label: t("marketplace.sortRateAsc") },
            { value: "rate_desc", label: t("marketplace.sortRateDesc") },
            { value: "experience_desc", label: t("marketplace.sortExperience") },
          ]}/>
      </div>

      <div className="grid gap-8 lg:grid-cols-[16rem_1fr]">
        <MarketplaceFilters variant="sidebar" value={filters} onChange={updateFilters} facets={facets} resultCount={total} showRate showExperience sortOptions={[
            { value: "relevance", label: t("marketplace.sortRelevance") },
            { value: "rate_asc", label: t("marketplace.sortRateAsc") },
            { value: "rate_desc", label: t("marketplace.sortRateDesc") },
            { value: "experience_desc", label: t("marketplace.sortExperience") },
          ]}/>

        <div className="min-w-0">
          {instructorsQuery.isLoading && <p className="rounded-2xl bg-[var(--ni-sage-soft)] p-5 text-sm ni-t-muted" aria-live="polite">{t("catalogue.loadingApprovedInstructors")}</p>}
          {discoveryFailed && <p role="alert" className="rounded-2xl bg-[var(--ni-clay-soft)] p-5 text-sm ni-t-clay">{t("catalogue.instructorDiscoveryUnavailable")}</p>}
          {!instructorsQuery.isLoading && !discoveryFailed && <>
            <div className="mb-5 flex flex-wrap items-center justify-between gap-2">
              <p className="text-sm font-semibold ni-t-muted">{t("catalogue.approvedInstructors")} · <span className="tabular">{total}</span></p>
              <span className="text-xs ni-t-muted-soft">{t("catalogue.publishedApprovedOnly")}</span>
            </div>
            {instructors.length ? <>
              <div className="stagger grid gap-5">
                {/* One card component, so the public marketplace and the learner
                    dashboard cannot drift into showing different fields. */}
                {instructors.map((instructor) => <InstructorCard
                  key={instructor.public_slug}
                  instructor={instructor}
                  href={(embedded ? "/dashboard/learner/teachers/" : "/teachers/") + instructor.public_slug}
                />)}
              </div>
              {total > pageSize && <nav className="mt-8 flex items-center justify-between gap-3" aria-label={t("marketplace.pagination")}>
                <Button type="button" variant="outline" disabled={page === 0} onClick={() => setPage((value) => Math.max(0, value - 1))}>{t("marketplace.previous")}</Button>
                <p className="text-xs ni-t-muted tabular">{t("marketplace.pageOf", { page: String(page + 1), pages: String(Math.max(1, Math.ceil(total / pageSize))) })}</p>
                <Button type="button" variant="outline" disabled={(page + 1) * pageSize >= total} onClick={() => setPage((value) => value + 1)}>{t("marketplace.next")}</Button>
              </nav>}
            </> : <div className="rounded-[1.35rem] border border-dashed border-[var(--ni-sage-mid)] bg-[var(--ni-sage-soft)] px-6 py-12 text-center">
              <h3 className="font-display text-2xl ni-t-ink">{t("marketplace.noMatches")}</h3>
              <p className="mx-auto mt-2 max-w-md text-sm leading-6 ni-t-muted">{t("marketplace.noMatchesCopy")}</p>
              <button type="button" onClick={() => updateFilters({ ...emptyFilters })} className="mt-5 rounded-full bg-[var(--ni-moss)] px-5 py-2.5 text-sm font-semibold text-white">{t("marketplace.clearFilters")}</button>
            </div>}
          </>}
        </div>
      </div>
    </main>{!embedded && <Footer/>}</>;
}

function TutorDetail({ slug }: { slug: string }) { return <PublicInstructorProfile slug={slug}/>; }
function RequirementDetail({ id }: { id: string }) { const { t } = useLocale(); const requirement = getLearnerRequirements().find((r) => r.id === id) ?? getLearnerRequirements()[0]; return <><Header/><PageIntro eyebrow={t("requirements.detailEyebrow")} title={t("requirements.detailTitle", { subject: requirement.subject.toLowerCase() })} copy={t("requirements.detailCopy")}/><main className="mx-auto max-w-5xl px-5 py-14 lg:px-8 lg:py-20"><div className="grid gap-8 lg:grid-cols-[1fr_.65fr]"><div className="rounded-[1.5rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-7"><div className="flex items-center justify-between"><Pill>{requirement.status}</Pill><span className="text-xs font-bold ni-t-muted-soft">{requirement.id}</span></div><h2 className="mt-6 font-display text-4xl ni-t-ink">{t("requirements.fit")}</h2><div data-reveal-stagger className="mt-8 grid gap-5 sm:grid-cols-2"><Info label={t("catalogue.subject")} value={requirement.subject}/><Info label={t("requirements.level")} value={requirement.level}/><Info label={t("requirements.language")} value={requirement.language}/><Info label={t("requirements.timezone")} value={requirement.timezone}/><Info label={t("requirements.schedule")} value={requirement.schedule}/><Info label={t("requirements.budget")} value={requirement.budget}/></div><div className="mt-8 border-t border-[var(--ni-sage)] pt-6 text-sm leading-6 ni-t-muted">{t("requirements.contactPrivate")}</div></div><aside className="rounded-[1.5rem] bg-[var(--ni-teal)] p-7 text-white"><Sparkles className="ni-t-gold-mid"/><h3 className="mt-6 font-display text-3xl">{t("requirements.teachingFit")}</h3><p className="mt-3 text-sm leading-6 ni-t-muted">{t("requirements.responseComing")}</p><Button href="/login" variant="quiet">{t("requirements.respond")} <ArrowRight size={16}/></Button></aside></div></main><Footer/></>; }
function RequirementsPage() { const { t } = useLocale(); return <><Header/><PageIntro eyebrow={t("requirements.eyebrow")} title={t("requirements.title")} copy={t("requirements.copy")}/><main className="mx-auto max-w-7xl px-5 py-12 lg:px-8 lg:py-16"><div className="mb-10 flex flex-wrap items-center justify-between gap-4"><div><Pill tone="gold">{t("requirements.demo")}</Pill><p className="mt-3 text-sm ni-t-muted">{t("requirements.sampleRequests", { count: getLearnerRequirements().length })}</p></div><Button href="/login">{t("requirements.post")} <ArrowRight size={16}/></Button></div><div data-reveal-stagger className="grid gap-5 lg:grid-cols-3">{getLearnerRequirements().map((r) => <div key={r.id} className="rounded-[1.35rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-6 shadow-sm"><div className="flex items-center justify-between"><Pill>{r.status}</Pill><span className="text-xs font-semibold ni-t-muted-soft">{r.id}</span></div><h2 className="mt-5 font-display text-3xl ni-t-ink">{t("requirements.lookingFor", { subject: r.subject })}</h2><div className="mt-5 space-y-3 text-sm ni-t-muted"><Info label={t("requirements.level")} value={r.level}/><Info label={t("requirements.language")} value={r.language}/><Info label={t("requirements.timezone")} value={r.timezone}/><Info label={t("requirements.schedule")} value={r.schedule}/><Info label={t("requirements.budget")} value={r.budget}/></div><Link href={`/requirements/${r.id}`} className="mt-6 inline-flex w-full items-center justify-center rounded-full border border-[var(--ni-sage-line)] py-3 text-sm font-bold ni-t-sage-ink">{t("requirements.view")} <ArrowRight size={15} className="ml-2"/></Link></div>)}</div></main><Footer/></>; }
function Info({ label, value }: { label: string; value: string }) { return <div className="flex items-start justify-between gap-4"><span className="ni-t-muted-soft">{label}</span><span className="text-right font-semibold ni-t-moss-deep">{value}</span></div>; }
function EmptyState({ title, copy }: { title: string; copy: string }) { return <div className="rounded-[1.5rem] border border-dashed border-[var(--ni-sage-mid)] bg-[var(--ni-sage-soft)] px-6 py-16 text-center"><div className="mx-auto flex h-12 w-12 items-center justify-center rounded-2xl bg-[var(--ni-sage-soft)] ni-link"><Search size={21}/></div><h2 className="mt-5 font-display text-3xl ni-t-ink">{title}</h2><p className="mx-auto mt-2 max-w-md text-sm leading-6 ni-t-muted">{copy}</p></div>; }
function AuthPage({ mode }: { mode: "login" | "signup" }) { const { t } = useLocale(); return <><Header/><main className="grid min-h-[calc(100vh-80px)] bg-[var(--ni-bg)] lg:grid-cols-2"><div className="relative hidden overflow-hidden lg:block"><img src={hero} alt="" className="h-full w-full object-cover"/><div className="absolute inset-0 bg-[var(--ni-teal)]/50"/><div className="absolute bottom-14 left-14 max-w-sm text-white"><p className="text-xs font-bold uppercase tracking-[.2em] ni-t-gold-mid">Zufishan</p><p className="mt-4 font-display text-5xl leading-tight">Your study desk, with a little more light.</p></div></div><div className="flex items-center px-6 py-16 lg:px-20"><div className="w-full max-w-md"><Pill tone="gold">Demo access</Pill><h1 className="mt-5 font-display text-5xl ni-t-ink">{mode === "login" ? "Return to your learning path." : "Make space for learning."}</h1><p className="mt-4 text-sm leading-6 ni-t-muted">Authentication is scaffolded for a future Supabase connection. No account is created in this demo phase.</p><form className="mt-8 space-y-4" onSubmit={(e) => e.preventDefault()}><label className="block text-sm font-semibold ni-t-moss-deep">Email<input type="email" placeholder="you@example.com" className="mt-2 w-full rounded-xl border border-[var(--ni-sage-line)] bg-[var(--ni-paper)] px-4 py-3 outline-none focus:border-[var(--ni-moss)]"/></label>{mode === "signup" && <label className="block text-sm font-semibold ni-t-moss-deep">{t("auth.signupRole")}<select className="mt-2 w-full rounded-xl border border-[var(--ni-sage-line)] bg-[var(--ni-paper)] px-4 py-3 outline-none"><option>Learner</option><option>Instructor</option></select></label>}<label className="block text-sm font-semibold ni-t-moss-deep">Password<input type="password" placeholder="••••••••" className="mt-2 w-full rounded-xl border border-[var(--ni-sage-line)] bg-[var(--ni-paper)] px-4 py-3 outline-none focus:border-[var(--ni-moss)]"/></label><Button onClick={() => {}}>{mode === "login" ? "Log in (demo)" : "Create account (demo)"} <ArrowRight size={16}/></Button></form><p className="mt-6 text-sm ni-t-muted">{mode === "login" ? "New to Zufishan? " : "Already have an account? "}<Link className="font-bold ni-link" href={mode === "login" ? "/signup" : "/login"}>{mode === "login" ? "Create an account" : "Log in"}</Link></p></div></div></main><Footer/></>; }
function DashboardShell({ role }: { role: "learner" | "instructor" | "admin" }) {
  // Each desk has its own overview now. Admin still uses the shared one; the
  // learner desk moved to LearnerOverview, which drops the demo banner and the
  // "Test error" toggle that were shipping to real accounts.
  if (role === "instructor") return <InstructorDashboard />;
  if (role === "learner") return <LearnerOverview />;
  return <DashboardOverview role={role} />;
}
function HowItWorksPage() { const { t } = useLocale(); const steps = [{ title: "Explore or describe", copy: "Browse courses and instructors, or post what you want to learn." }, { title: "Compare with context", copy: "Use subject, language, level, time zone, and teaching style to narrow the fit." }, { title: "Request a trial", copy: "Trial requests and enrolment are planned connection points, not live payments." }, { title: "Learn and keep going", copy: "A future classroom and progress layer will make the learning path visible." }]; return <><Header/><PageIntro eyebrow={t("nav.help")} title={t("home.nextTitle")} copy={t("dashboard.notice")}/><main className="mx-auto max-w-6xl px-5 py-14 lg:px-8 lg:py-20"><div className="grid gap-5 md:grid-cols-2">{steps.map((step, i) => <div key={step.title} className="relative rounded-[1.5rem] border border-[var(--ni-sage)] bg-[var(--ni-paper)] p-7"><span className="text-xs font-bold uppercase tracking-[.2em] ni-t-gold">Step {String(i + 1).padStart(2, "0")}</span><h2 className="mt-8 font-display text-3xl ni-t-ink">{step.title}</h2><p className="mt-3 text-sm leading-7 ni-t-muted">{step.copy}</p></div>)}</div><div className="mt-10 grid gap-5 lg:grid-cols-3"><div className="rounded-2xl bg-[var(--ni-sage-soft)] p-6"><Clock3 className="ni-t-gold"/><h3 className="mt-5 font-display text-2xl ni-t-ink">Timezone-aware</h3><p className="mt-2 text-sm leading-6 ni-t-muted">Availability and scheduling should respect real lives and different locations.</p></div><div className="rounded-2xl bg-[var(--ni-sage-soft)] p-6"><ShieldCheck className="ni-t-gold"/><h3 className="mt-5 font-display text-2xl ni-t-ink">Safety by design</h3><p className="mt-2 text-sm leading-6 ni-t-muted">Privacy, moderation, and transparent verification are foundational placeholders.</p></div><div className="rounded-2xl bg-[var(--ni-sage-soft)] p-6"><MessageCircle className="ni-t-gold"/><h3 className="mt-5 font-display text-2xl ni-t-ink">Classroom coming soon</h3><p className="mt-2 text-sm leading-6 ni-t-muted">The browser classroom is planned, but no live video or production messaging is connected here.</p></div></div></main><Footer/></>; }
function SimpleInfoPage({ title, eyebrow, copy }: { title: string; eyebrow: string; copy: string }) { return <><Header/><PageIntro eyebrow={eyebrow} title={title} copy={copy}/><main className="mx-auto max-w-4xl px-5 py-14 lg:px-8 lg:py-20"><div className="grid gap-4 sm:grid-cols-2">{["Discover a direction", "Connect with context", "Learn at your pace", "Grow with intention"].map((item, i) => <div className="ni-card p-7" key={item}><span className="text-xs font-bold uppercase tracking-[.2em] ni-t-gold">{String(i + 1).padStart(2, "0")}</span><h2 className="mt-8 font-display text-3xl ni-t-ink">{item}</h2><p className="mt-3 text-sm leading-6 ni-t-muted">A clear, human placeholder for the connected workflow that follows this foundation.</p></div>)}</div></main><Footer/></>; }
